module top_module(
    input [3:0] in,
    input [1:0] sel,
    input enable,
    input clk,           // Added clk input
    output reg out       // Changed output to reg type
);reg [3:0] reg_in [0:1];
reg [1:0] reg_sel [0:1];
reg reg_enable;

always @(posedge clk) begin
    reg_in[1] <= reg_in[0];
    reg_in[0] <= in;
    reg_sel[1] <= reg_sel[0];
    reg_sel[0] <= sel;
    reg_enable <= enable;
end

always @(*) begin
    out = (reg_enable) ? reg_in[1][reg_sel[1]] : 1'bz; // Always block for combinational logic
end

endmodule

