module top_module (
	input clk,
	input areset,
	input x,
	input y,
	output z);parameter GE=0, LT=1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= GE;
		else begin
			case (state)
				GE: state <= (x >= y) ? GE : LT;
				LT: state <= LT;
			endcase
		end
	end

	assign z = (state == GE);

endmodule

