Design a circuit that detects and signals an event based on two rotary inputs, `rot_a` and `rot_b`, synchronized with a clock signal. The output `r_event` is set to HIGH when both rotary inputs are HIGH and reset to LOW when both are LOW, creating a condition-sensitive output that responds to the simultaneous state of the rotary inputs.
module top_module( clk,rot_a,rot_b,r_event
    );

code:
module top_module( clk,rot_a,rot_b,r_event
    );input clk;
	  input rot_a;
	  input rot_b;
	  output r_event;
	  reg r_event;
	  always @(posedge clk) begin
	  if(rot_a==1 && rot_b==1) begin
	    r_event <= 1;
	    end
	  if(rot_a==0 && rot_b==0) begin
	    r_event <= 0;
	    end
	  end

endmodule

