module top_module(
  input        reset,
  input        wr_clk,
  input        rd_clk,
  input  [7:0] wr_data,
  input        wr_en,
  input        rd_en,
  output reg [7:0] rd_data,  // Changed to reg to hold the output value
  output       empty,
  output       full
);parameter AW = 4; // Number of bits to access all the entries
  parameter DEPTH = 16; // Depth of the FIFO buffer

  //##########
  //# REGISTERS
  //##########
  reg [7:0] buffer [0:DEPTH-1];
  reg [AW:0] wr_ptr;
  reg [AW:0] rd_ptr;
  reg        empty_reg; // Renamed from empty to empty_reg
  reg        full_reg;  // Renamed from full to full_reg

  //##########
  //# WIRES
  //##########
  wire [AW:0] wr_ptr_next;
  wire [AW:0] rd_ptr_next;
  wire        empty_next;
  wire        full_next;

  //################
  //# WRITE POINTER
  //################
  assign wr_ptr_next = wr_ptr + 1'b1;
  always @(posedge wr_clk or posedge reset) begin
    if (reset) begin
      wr_ptr <= 0;
    end else if (wr_en && !full_reg) begin
      wr_ptr <= wr_ptr_next;
    end
  end

  //################
  //# READ POINTER
  //################
  assign rd_ptr_next = rd_ptr + 1'b1;
  always @(posedge rd_clk or posedge reset) begin
    if (reset) begin
      rd_ptr <= 0;
    end else if (rd_en && !empty_reg) begin
      rd_ptr <= rd_ptr_next;
    end
  end

  //############
  //# FIFO LOGIC
  //############
  assign empty_next = (wr_ptr == rd_ptr) && !full_reg;
  assign full_next = (wr_ptr_next == rd_ptr) && !empty_reg;

  always @(posedge wr_clk or posedge rd_clk or posedge reset) begin
    if (reset) begin
      empty_reg <= 1;
      full_reg <= 0;
    end else begin
      empty_reg <= empty_next;
      full_reg <= full_next;
      if (wr_en && !full_reg) begin
        buffer[wr_ptr] <= wr_data;
      end
      if (rd_en && !empty_reg) begin
        rd_data <= buffer[rd_ptr];
      end
    end
  end

  // Assign outputs from registers
  assign empty = empty_reg;
  assign full = full_reg;

endmodule

module top_module(
	data1_i,
	data2_i,
	ALUCtrl_i,
	data_o, 
	Zero_o 
);input [31:0] data1_i;
input [31:0] data2_i;
input [3:0] ALUCtrl_i;
output reg [31:0] data_o;
output Zero_o; 

parameter ALUCtrl_add = 4'b0010;
parameter ALUCtrl_sub = 4'b0110;
parameter ALUCtrl_and = 4'b0000;
parameter ALUCtrl_or = 4'b0001;
parameter ALUCtrl_mul = 4'b0111; 

assign Zero_o = (data_o == 32'b0)? 1'b1:1'b0; 

always @(*) begin
	case(ALUCtrl_i)
		ALUCtrl_add: data_o <= data1_i + data2_i;
		ALUCtrl_sub: data_o <= data1_i - data2_i;
		ALUCtrl_and: data_o <= data1_i & data2_i;
		ALUCtrl_or: data_o <= data1_i | data2_i;
		ALUCtrl_mul: data_o <= data1_i * data2_i;
		default: data_o <= data1_i + data2_i;
	endcase
end

endmodule

