description:
Design a circuit that calculates the next highest 4-bit binary number from a given 4-bit input. The module takes a 4-bit input and increments it by 1. If the incremented value equals 15 (binary 1111), it wraps around and outputs 0 (binary 0000). The output is registered, with the result being updated on the positive edge of the clock signal.
module top_module(
    input [3:0] in,
    input clk,            // Added clk as an input
    output reg [3:0] out
);

code:
module top_module(
    input [3:0] in,
    input clk,            // Added clk as an input
    output reg [3:0] out
);reg [3:0] stage1_out;
reg [3:0] stage2_out;

always @(*) begin
    stage1_out = in + 1;
end

always @(*) begin
    if (stage1_out == 4'b1111) begin
        stage2_out = 4'b0000;
    end else begin
        stage2_out = stage1_out;
    end
end

always @(posedge clk) begin
    out <= stage2_out;
end

endmodule

