module top_module(
  input clk,
  input areset,
  input start,
  input [7:0] A,
  input [7:0] B,
  output reg [15:0] P,
  output reg done
);reg [7:0] a_reg;
  reg [7:0] b_reg;
  reg [3:0] state;
  reg [1:0] count;
  reg [7:0] m_reg;
  reg [15:0] p_reg;

  always @(posedge clk or negedge areset) begin
    if (areset == 0) begin
      state <= 0;
      count <= 0;
      a_reg <= 0;
      b_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
      P <= 0;
      done <= 0;
    end else begin
      case (state)
        0: begin
          if (start) begin
            a_reg <= A;
            b_reg <= B;
            m_reg <= {b_reg, 1'b0};
            p_reg <= 0;
            count <= 0;
            state <= 1;
          end
        end
        1: begin
          if (count == 3) begin
            count <= 0;
            state <= 2;
          end else begin
            if (m_reg[1:0] == 2'b01) begin
              p_reg <= p_reg + (a_reg << 1);
            end else if (m_reg[1:0] == 2'b10) begin
              p_reg <= p_reg + (a_reg << 1) + a_reg;
            end
            m_reg <= {m_reg[6:0], m_reg[0]};
            count <= count + 1;
          end
        end
        2: begin
          if (count == 7) begin
            P <= p_reg[15:0];
            done <= 1;
            state <= 0;
          end else begin
            m_reg <= {m_reg[6:0], m_reg[0]};
            count <= count + 1;
            state <= 3;
          end
        end
        3: begin
          if (count == 3) begin
            count <= 0;
            state <= 1;
          end else begin
            if (m_reg[1:0] == 2'b01) begin
              p_reg <= p_reg + (a_reg << 1);
            end else if (m_reg[1:0] == 2'b10) begin
              p_reg <= p_reg + (a_reg << 1) + a_reg;
            end
            m_reg <= {m_reg[6:0], m_reg[0]};
            count <= count + 1;
            state <= 2;
          end
        end
      endcase
    end
  end

endmodule

