description:
Design a circuit that reverses the bit order of a 100-bit input signal. The module captures the incoming bits into a shift register and, on each clock cycle, shifts the bits while simultaneously loading the least significant bit of the input. The output reflects the stored bits in reverse order, facilitating applications that require data manipulation such as encoding or signal processing tasks.
module top_module(
    input clk,
    input [99:0] in,
    output [99:0] out
);

code:
module top_module(
    input clk,
    input [99:0] in,
    output [99:0] out
);reg [99:0] shift_reg;
wire [99:0] reversed;

assign reversed[0] = shift_reg[99];

genvar i;
generate
    for (i = 1; i < 100; i = i + 1) begin : SHIFT_LOOP
        assign reversed[i] = shift_reg[99-i];
    end
endgenerate

assign out = reversed;

always @(posedge clk) begin
    shift_reg <= {shift_reg[98:0], in[0]};
end

endmodule

