assign ALU_operation_o[0] = (ALUOp_i == 3'b100) ? 1'b0 : (funct_i[0] ^ funct_i[1]) & (funct_i[2] ^ funct_i[3]);

assign FURslt_o = (ALUOp_i == 3'b101) ? 2'd2 :(ALUOp_i == 3'b010 & funct_i[5] == 1'b0) ? 2'd1: 2'd0;

