module debounce(
  input clk,
  input rst_n,
  input button_in,
  output reg button_out
);

  reg [3:0] shift_reg;
  reg [3:0] counter;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      shift_reg <= 4'b0000;
      counter <= 4'b0000;
      button_out <= 1'b0;
    end
    else begin
      shift_reg <= {shift_reg[2:0], button_in};
      if (shift_reg[3:0] == 4'b1111)
        counter <= counter + 1;
      else
        counter <= 4'b0000;

      if (counter == 4'b1111)
        button_out <= 1'b1;
      else if (counter == 4'b0000)
        button_out <= 1'b0;
    end
  end

endmodule

