module shift_register (D, CLK, RST, LOAD, SI, Q);
input [3:0] D;
input CLK, RST, LOAD, SI;
output reg [3:0] Q;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Q <= 4'b0000;
    end else if (LOAD) begin
        Q <= D;
    end else begin
        Q <= {Q[2:0], SI};
    end
end

endmodule

