module MagnitudeComparator (
    input [3:0] a,
    input [3:0] b,
    output reg less,
    output reg equal,
    output reg greater
);
    always @(*) begin
        if (a < b) begin
            less = 1'b1;
            equal = 1'b0;
            greater = 1'b0;
        end else if (a == b) begin
            less = 1'b0;
            equal = 1'b1;
            greater = 1'b0;
        end else begin
            less = 1'b0;
            equal = 1'b0;
            greater = 1'b1;
        end
    end
endmodule

module top_module(
    input [1:0] coin,
    input reset,
    output reg dispense,   // Change dispense to reg type
    output reg [1:0] change
);reg [5:0] total_amount;

always @(*) begin
    if(reset) begin
        total_amount <= 0;
        change <= 0;
        dispense <= 0;
    end else begin
        total_amount <= total_amount + {4'b0000, coin}; // Adjust to 6 bits
        if(total_amount >= 6'b1010) begin
            dispense <= 1;
            change <= total_amount - 6'b1010;
            total_amount <= 0;
        end else begin
            dispense <= 0;
        end
    end
end

endmodule

description:
Design a dual-port RAM module with asynchronous read and write capabilities. It has a parameterized data width and depth, allowing for customizable configurations. The memory is cleared on a reset signal, and the module supports simultaneous reading and writing, using separate pointers for read and write operations. The output provides the stored data at the specified read address when the read enable signal is active.
module top_module(clk, wr_enb, rd_enb, rst, rd_ptr, wr_ptr,
		      data_in, data_out);

code:
module top_module(clk, wr_enb, rd_enb, rst, rd_ptr, wr_ptr,
		      data_in, data_out);parameter RAM_WIDTH = 10;
   parameter RAM_DEPTH = 8;
   parameter PTR_SIZE = 3;

   input clk, wr_enb, rd_enb, rst;
   input [RAM_WIDTH-1:0] data_in;
   input [PTR_SIZE-1:0]  rd_ptr, wr_ptr;
   output reg [RAM_WIDTH-1:0] data_out;

   reg [RAM_WIDTH-1:0] 	      mem[RAM_DEPTH-1:0];
   integer 		      i;

   always @(posedge clk) begin

      if (rst) begin
	 for (i=0; i<RAM_DEPTH; i=i+1)
	   mem[i] <= 0;
	 data_out <= 0;
      end

      else begin
	 if (wr_enb)
	   mem[wr_ptr] <= data_in;
	 if (rd_enb)
	   data_out <= mem[rd_ptr];
      end 
   end 

endmodule

