    input stb_in,
    input signed [23:0] data_in,
    output stb_out,
    output signed [23:0] data_out,
    output [15:0] count_out
);parameter N = 4; // Number of samples to average

    reg [23:0] sum_reg; // Register to hold the sum of the input samples
    reg [15:0] count_reg; // Register to hold the number of input samples processed
    reg [23:0] avg_reg; // Register to hold the average of the input samples
    reg [23:0] data_out_reg; // Register to hold the output data
    reg stb_out_reg; // Register to hold the strobe output

    assign count_out = count_reg;

    always @(posedge clk) begin
        if (rst) begin
            sum_reg <= 0;
            count_reg <= 0;
            avg_reg <= 0;
            data_out_reg <= 0;
            stb_out_reg <= 0;
        end else begin
            if (bypass) begin
                data_out_reg <= data_in;
                stb_out_reg <= stb_in;
            end else begin
                if (run) begin
                    if (stb_in) begin
                        sum_reg <= sum_reg + data_in;
                        count_reg <= count_reg + 1;
                        if (count_reg == N) begin
                            avg_reg <= sum_reg / N;
                            data_out_reg <= avg_reg;
                            stb_out_reg <= 1;
                            sum_reg <= 0;
                            count_reg <= 0;
                        end else begin
                            stb_out_reg <= 0;
                        end
                    end else begin
                        stb_out_reg <= 0;
                    end
                end else begin
                    stb_out_reg <= 0;
                end
            end
        end
    end

    assign stb_out = stb_out_reg;
    assign data_out = data_out_reg;

endmodule

