module fan_controller (
        input clk,
        input areset,
        input turn_on,
        input turn_off,
        output reg fan_on);parameter Fan_Off=1'b0, Fan_On=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Fan_Off;
		else begin
			case (state)
				Fan_Off: state <= turn_on ? Fan_On : Fan_Off;
				Fan_On: state <= turn_off ? Fan_Off : Fan_On;
			endcase
		end
	end

	assign fan_on = (state == Fan_On);

endmodule

