module top_module(
  input clk,
  input reset,
  input [7:0] parallel_in,
  input serial_in,
  output [7:0] parallel_out,
  output serial_out
);reg [3:0] counter_out;
  reg [7:0] register_out;
  reg select_input;

  // 4-bit binary counter with synchronous reset to 0
  always @(posedge clk) begin
    if (reset) begin
      counter_out <= 4'b0000;
    end else begin
      counter_out <= counter_out + 1;
    end
  end

  // 8-bit register with synchronous reset to 0
  always @(posedge clk) begin
    if (reset) begin
      register_out <= 8'b00000000;
    end else begin
      register_out <= parallel_in;
    end
  end

  // Functional module to select between serial and parallel input
  always @(posedge clk) begin
    if (reset) begin
      select_input <= 1'b0;
    end else begin
      select_input <= counter_out[0] ^ register_out[0];
    end
  end

  // Shift register implementation
  reg [7:0] shift_register [0:3];
  always @(posedge clk) begin
    if (reset) begin
      shift_register[0] <= 8'b0;
      shift_register[1] <= 8'b0;
      shift_register[2] <= 8'b0;
      shift_register[3] <= 8'b0;
    end else begin
      if (select_input) begin
        // Shift in serial input
        shift_register[0] <= serial_in;                     // Shift in the new bit
        shift_register[1] <= shift_register[0];             // Shift elements
        shift_register[2] <= shift_register[1];
        shift_register[3] <= shift_register[2];
      end else begin
        // Shift in parallel input
        shift_register[0] <= register_out[0];              // Assuming we want to shift in only the least significant bit of the parallel register
        shift_register[1] <= shift_register[0];
        shift_register[2] <= shift_register[1];
        shift_register[3] <= shift_register[2];
      end
    end
  end

  // Output the parallel output and the serial output
  assign parallel_out = shift_register[3];
  assign serial_out = shift_register[0][0]; // Assuming you want the first bit as serial out

endmodule

