module top_module(
  input [1:0] address,
  input chipselect,
  input clk,
  input reset_n,
  input write_n,
  input [31:0] writedata,
  output reg [9:0] out_port,
  output reg [31:0] readdata
);reg [9:0] data_out;
  reg [9:0] read_mux_out;

  always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
      data_out <= 10'b1111;
    end else if (!chipselect) begin
      if (!write_n) begin
        case (address)
          2'b00: data_out[9:0] <= writedata[9:0];
          default: data_out[9:0] <= data_out[9:0];
        endcase
      end else begin
        case (address)
          2'b00: read_mux_out[9:0] <= data_out[9:0];
          default: read_mux_out[9:0] <= 10'b0;
        endcase
      end
    end

    out_port <= data_out;
    readdata <= { 22'b0, read_mux_out };
  end

endmodule

