description:
Design a 2-bit state machine with a 4-bit output that cycles through four states on each clock cycle. The state transitions are dictated by the current state: from 00 to 01 to 10 to 11, then back to 00. When the state changes, the output changes according to the current state, specifically outputting 4'b1000, 4'b0100, 4'b0010, and 4'b0001 for states 00, 01, 10, and 11 respectively. The machine can be reset asynchronously using the clear (clr) signal, which sets the current state to 00.
module top_module(
    input clk,clr,
    output reg [3:0] out
);

code:
module top_module(
    input clk,clr,
    output reg [3:0] out
);reg [1:0] current_state,next_state;
    always @(posedge clk or negedge clr) begin
        if (!clr) begin
            current_state <= 2'b00;
        end else begin
            current_state <= next_state;
        end
    end
    always @(current_state) begin
        case (current_state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = 2'b10;
            2'b10: next_state = 2'b11;
            2'b11: next_state = 2'b00;
        endcase
    end
    always @(posedge clk or negedge clr) begin
        case (current_state)
            2'b00:out<=4'b1000;
            2'b01:out<=4'b0100;
            2'b10:out<=4'b0010;
            2'b11:out<=4'b0001;
        endcase
    end
endmodule

module top_module(
    input clk,
    input in,
    input reset,
    output reg out
);     // State Encoding
    parameter A = 0, B = 1, C = 2, D = 3;
    reg [1:0] state, next;

    // State Transition Logic
    always @(*) begin
        case (state)
            A: next = in ? C : D;
            B: next = in ? B : C;
            C: next = in ? D : B;
            D: next = in ? C : D;
        endcase
    end

    // State Register with synchronous Reset
    always @(posedge clk) begin
        if (reset) state <= C;
        else state <= next;
    end

    // Output Logic
    always @(*) begin
        case (state)
            A: out = 1;
            B: out = 1;
            C: out = 0;
            D: out = 0;
        endcase
    end
endmodule

