module top_module(
  input clk,
  input reset,
  input data,
  output reg match
);parameter S_RESET = 2'b00, S_1 = 2'b01, S_2 = 2'b10, S_3 = 2'b11;
  reg [1:0] state;
  reg [2:0] shift_reg;

  always @(posedge clk) begin
    if (reset) begin
      state <= S_RESET;
      shift_reg <= 3'b0;
      match <= 0;
    end
    else begin
      case (state)
        S_RESET: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_1;
          end
        end

        S_1: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_2;
          end
        end

        S_2: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_3;
          end
        end

        S_3: begin
          shift_reg <= {shift_reg[1:0], data};
          if (shift_reg == 3'b101) begin
            match <= 1;
            state <= S_RESET;
          end
          else begin
            match <= 0;
            state <= S_1;
          end
        end
      endcase
    end
  end

endmodule

