module top_module(clk, set,qout,reset,light,pause, cout, count_sum);input clk,reset,light,pause;
input [6:0] set;
output cout;
output [6:0] qout;
output [9:0] count_sum;
reg [6:0] qout = 0;
reg [9:0] count_sum = 0;
always @(negedge clk or posedge reset)
begin
if(reset == 1) begin
qout=0;
count_sum = 0;
end
else 
begin
if(pause)
;
else
if(qout[6:0]==set)
        qout[6:0]=0;
   else if(light==1)
   qout[6:0]=qout[6:0]+1;
   if(qout!=0&&pause==0)    
   count_sum = count_sum + 1;
end
end

